rollupOptions: {
  output: {
    manualChunks(id) {
      if (!id.includes("node_modules")) return undefined;
      // @react-pdf and its pdf-only dependency tree are heavy (~1 MB min)
      // and only reachable via the dynamic import() in the reports buttons,
      // so keep them out of the eager catch-all "vendor" chunk. Shared deps
      // (pako, scheduler, tslib, …) intentionally stay in their usual chunks.
      if (
        /node_modules\/(@react-pdf|fontkit|yoga-layout|brotli|restructure|dfa|tiny-inflate|unicode-properties|unicode-trie|linebreak|png-js|jay-peg|bidi-js|hyphen|media-engine|browserify-zlib|vite-compatible-readable-stream|js-md5|abs-svg-path|normalize-svg-path|svg-arc-to-cubic-bezier|parse-svg-path|hsl-to-hex|hsl-to-rgb-for-reals|emoji-regex-xs)\//.test(
          id,
        )
      )
        return "vendor-pdf";
      if (id.includes("motion") || id.includes("framer-motion")) return "vendor-motion";
      if (id.includes("@tanstack")) return "vendor-query";
      if (id.includes("@radix-ui") || id.includes("radix-ui")) return "vendor-radix";
      if (id.includes("lucide-react")) return "vendor-lucide";
      // Keep React core, react-dom and scheduler in ONE chunk. Splitting
      // react core into the catch-all "vendor" chunk creates a circular
      // cross-chunk import (react-dom -> react) that loads react-dom before
      // React initialises, crashing with a __SECRET_INTERNALS undefined error.
      if (
        id.includes("node_modules/react-dom") ||
        id.includes("node_modules/react/") ||
        id.includes("node_modules/scheduler/") ||
        id.includes("react/jsx-runtime") ||
        id.includes("react/jsx-dev-runtime")
      )
        return "vendor-react";
      if (id.includes("wouter")) return "vendor-router";
      if (id.includes("zod") || id.includes("drizzle-zod") || id.includes("@hookform")) return "vendor-forms";
      // No catch-all "vendor" bucket: it merged every remaining node_module
      // (incl. @react-pdf + yoga, recharts, stripe — ~3.5 MB) into a single
      // chunk that index.html loaded eagerly, defeating the dynamic import()
      // of the PDF generators. Returning undefined lets Rollup place each dep
      // with the chunk(s) that import it, so dynamic-only deps stay lazy.
      return undefined;
    },
  },

