content.content:
1	/* The four Property Management reports (Rent Roll, Collection Statement, Aged
2	   Arrears, Annual Income Statement). Each builder is a plain function returning a
3	   @react-pdf <Document> composed from the shared primitives — no hooks, so the
4	   dispatcher can call them directly and hand the element to savePdf().
5	
6	   Data comes straight from the property page caches: tenants (tenantProfiles),
7	   invoices (invoicesRentRequests) and schedules (activeSchedules). Nothing here
8	   fetches. Money is in integer cents throughout. */
9	import React from "react";
10	import { Document } from "@react-pdf/renderer";
11	
12	import {
13	  ReportPage, SectionTitle, KpiRow, DataTable, Money, StatusText,
14	  type Column, type MerchantHeader,
15	} from "../components";
16	import {
17	  fmtNZD, fmtDate, dateRangeLabel, calcGST, daysOverdue,
18	  inRange, agedBuckets, sumCents, ratePct, fmtPct, buildCSV,
19	} from "../../report-utils";
20	import { savePdf, downloadCsv } from "../savePdf";
21	import type { ReportFormat, DateRange } from "./types";
22	
23	export interface PropertyReportData {
24	  merchant: MerchantHeader;
25	  tenants: any[];
26	  invoices: any[];
27	  schedules: any[];
28	  /** Selected property address when the page is filtered to one property — the
29	     data is already narrowed to it; this just labels the report header. */
30	  scope?: string;
31	}
32	
33	/* ── Shared domain helpers ──────────────────────────────────────────── */
34	
35	const isPaid = (i: any) => i.status === "paid" || i.status === "paid_external";
36	const isVoided = (i: any) => i.status === "voided";
37	const isOverdue = (i: any, now: Date) =>
38	  !isPaid(i) && !isVoided(i) && i.dueAt != null && new Date(i.dueAt).getTime() < now.getTime();
39	
40	const tenantName = (t: any) => [t?.firstName, t?.lastName].filter(Boolean).join(" ").trim() || "—";
41	const byId = (tenants: any[]) => new Map<string, any>(tenants.map((t) => [t.id, t]));
42	const addressOf = (i: any, tmap: Map<string, any>) =>
43	  i.propertyAddress ?? tmap.get(i.tenantProfileId)?.propertyAddress ?? "—";
44	const tenantOf = (i: any, tmap: Map<string, any>) => {
45	  const t = tmap.get(i.tenantProfileId);
46	  return t ? tenantName(t) : i.tenantName ?? "—";
47	};
48	
49	type StatusKind = "paid" | "overdue" | "sent" | "muted";
50	function displayStatus(i: any, now: Date): { kind: StatusKind; label: string } {
51	  if (isPaid(i)) return { kind: "paid", label: "Paid" };
52	  if (isVoided(i)) return { kind: "muted", label: "Voided" };
53	  if (isOverdue(i, now)) return { kind: "overdue", label: "Overdue" };
54	  return { kind: "sent", label: "Sent" };
55	}
56	
57	const FREQ: Record<string, string> = { weekly: "wk", fortnightly: "fn", monthly: "mo" };
58	const rentLabel = (s: any) => (s ? `${fmtNZD(s.amountCents)}/${FREQ[s.frequency] ?? s.frequency}` : "—");
59	
60	/** Prefix a report's period line with the selected property, when scoped. */
61	const scopePrefix = (data: PropertyReportData) => (data.scope ? `${data.scope}  ·  ` : "");
62	
63	const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
64	/** Whole-dollar money with no cents — keeps the 12 annual columns narrow. */
65	const money0 = (c: number) => (c <= 0 ? "—" : "$" + Math.round(c / 100).toLocaleString("en-NZ"));
66	
67	/* ── 1 · Rent Roll (snapshot of every active tenancy) ───────────────── */
68	
69	interface RollRow {
70	  address: string;
71	  name: string;
72	  rent: string;
73	  lastPaid: string;
74	  status: { kind: StatusKind; label: string };
75	  outstandingCents: number;
76	}
77	
78	function rentRollRows(data: PropertyReportData, now: Date): RollRow[] {
79	  const activeSched = new Map<string, any>();
80	  for (const s of data.schedules) {
81	    if (s.status && s.status !== "active") continue;
82	    if (!activeSched.has(s.tenantProfileId)) activeSched.set(s.tenantProfileId, s);
83	  }
84	  const invByTenant = new Map<string, any[]>();
85	  for (const i of data.invoices) {
86	    const arr = invByTenant.get(i.tenantProfileId) ?? [];
87	    arr.push(i);
88	    invByTenant.set(i.tenantProfileId, arr);
89	  }
90	
91	  return data.tenants
92	    .filter((t) => t.status !== "archived")
93	    .map((t) => {
94	      const invs = invByTenant.get(t.id) ?? [];
95	      const paid = invs.filter(isPaid);
96	      const lastPaidAt = paid.reduce<Date | null>((acc, i) => {
97	        const d = i.paidAt ? new Date(i.paidAt) : null;
98	        return d && (!acc || d > acc) ? d : acc;
99	      }, null);
100	      const outstanding = invs.filter((i) => !isPaid(i) && !isVoided(i));
101	      const outstandingCents = sumCents(outstanding, (i) => i.amountCents ?? 0);
102	      const status = outstanding.some((i) => isOverdue(i, now))
103	        ? { kind: "overdue" as const, label: "Overdue" }
104	        : outstandingCents === 0 && paid.length > 0
105	          ? { kind: "paid" as const, label: "Paid" }
106	          : outstanding.length > 0
107	            ? { kind: "sent" as const, label: "Sent" }
108	            : { kind: "muted" as const, label: "—" };
109	      return {
110	        address: t.propertyAddress ?? "—",
111	        name: tenantName(t),
112	        rent: rentLabel(activeSched.get(t.id)),
113	        lastPaid: lastPaidAt ? fmtDate(lastPaidAt) : "—",
114	        status,
115	        outstandingCents,
116	      };
117	    })
118	    .sort((a, b) => a.address.localeCompare(b.address));
119	}
120	
121	function RentRollDoc(data: PropertyReportData) {
122	  const now = new Date();
123	  const rows = rentRollRows(data, now);
124	  const totalOutstanding = rows.reduce((s, r) => s + r.outstandingCents, 0);
125	  const overdueCount = rows.filter((r) => r.status.label === "Overdue").length;
126	
127	  const columns: Column<RollRow>[] = [
128	    { header: "Property", flex: 3, render: (r) => r.address },
129	    { header: "Tenant", flex: 2.2, render: (r) => r.name },
130	    { header: "Rent", flex: 1.5, align: "right", render: (r) => r.rent },
131	    { header: "Last Paid", flex: 1.4, align: "right", render: (r) => r.lastPaid },
132	    { header: "Status", flex: 1.4, align: "center", render: (r) => <StatusText kind={r.status.kind} label={r.status.label} /> },
133	    { header: "Outstanding", flex: 1.7, align: "right", render: (r) => <Money cents={r.outstandingCents} /> },
134	  ];
135	  const foot = ["Total", "", "", "", "", fmtNZD(totalOutstanding)];
136	
137	  return (
138	    <Document title="Rent Roll">
139	      <ReportPage merchant={data.merchant} title="Rent Roll" period={`${scopePrefix(data)}As at ${fmtDate(now)}  ·  ${rows.length} active tenancies`}>
140	        <KpiRow
141	          items={[
142	            { label: "Active Tenancies", value: String(rows.length) },
143	            { label: "Outstanding", value: fmtNZD(totalOutstanding), sub: "across portfolio" },
144	            { label: "Overdue Tenancies", value: String(overdueCount) },
145	          ]}
146	        />
147	        <SectionTitle>Tenancies</SectionTitle>
148	        <DataTable columns={columns} rows={rows} foot={foot} emptyText="No active tenancies." />
149	      </ReportPage>
150	    </Document>
151	  );
152	}
153	
154	/* ── 2 · Collection Statement (period-filtered) ─────────────────────── */
155	
156	interface CollRow {
157	  date: string;
158	  tenant: string;
159	  property: string;
160	  amountCents: number;
161	  status: { kind: StatusKind; label: string };
162	  paid: string;
163	  _paid: boolean;
164	}
165	
166	function collectionRows(data: PropertyReportData, range: DateRange): CollRow[] {
167	  const tmap = byId(data.tenants);
168	  const now = new Date();
169	  return data.invoices
170	    .filter((i) => !isVoided(i))
171	    .filter((i) => inRange(i.createdAt, range.start, range.end))
172	    .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime())
173	    .map((i) => ({
174	      date: fmtDate(i.createdAt),
175	      tenant: tenantOf(i, tmap),
176	      property: addressOf(i, tmap),
177	      amountCents: i.amountCents ?? 0,
178	      status: displayStatus(i, now),
179	      paid: i.paidAt ? fmtDate(i.paidAt) : "—",
180	      _paid: isPaid(i),
181	    }));
182	}
183	
184	function CollectionStatementDoc(data: PropertyReportData, range: DateRange) {
185	  const rows = collectionRows(data, range);
186	  const invoiced = sumCents(rows, (r) => r.amountCents);
187	  const paidRows = rows.filter((r) => r._paid);
188	  const collected = sumCents(paidRows, (r) => r.amountCents);
189	  const overdueCount = rows.filter((r) => r.status.label === "Overdue").length;
190	  const rate = ratePct(paidRows.length, rows.length);
191	
192	  const columns: Column<CollRow>[] = [
193	    { header: "Date", flex: 1.4, render: (r) => r.date },
194	    { header: "Tenant", flex: 2.2, render: (r) => r.tenant },
195	    { header: "Property", flex: 3, render: (r) => r.property },
196	    { header: "Amount", flex: 1.5, align: "right", render: (r) => <Money cents={r.amountCents} /> },
197	    { header: "Status", flex: 1.4, align: "center", render: (r) => <StatusText kind={r.status.kind} label={r.status.label} /> },
198	    { header: "Paid", flex: 1.4, align: "right", render: (r) => r.paid },
199	  ];
200	  const foot = ["Total", "", "", fmtNZD(invoiced), "", ""];
201	
202	  return (
203	    <Document title="Collection Statement">
204	      <ReportPage merchant={data.merchant} title="Collection Statement" period={`${scopePrefix(data)}${dateRangeLabel(range.start, range.end)}`}>
205	        <KpiRow
206	          items={[
207	            { label: "Invoiced", value: fmtNZD(invoiced), sub: `${rows.length} invoices` },
208	            { label: "Collected", value: fmtNZD(collected) },
209	            { label: "Collection Rate", value: fmtPct(rate) },
210	            { label: "Overdue", value: String(overdueCount) },
211	          ]}
212	        />
213	        <SectionTitle>Invoices</SectionTitle>
214	        <DataTable columns={columns} rows={rows} foot={foot} emptyText="No invoices sent in this period." />
215	      </ReportPage>
216	    </Document>
217	  );
218	}
219	
220	function collectionCsv(data: PropertyReportData, range: DateRange) {
221	  const rows = collectionRows(data, range);
222	  const headers = ["Date", "Tenant", "Property", "Amount (NZD)", "Status", "Paid Date"];
223	  const body = rows.map((r) => [r.date, r.tenant, r.property, (r.amountCents / 100).toFixed(2), r.status.label, r.paid]);
224	  return { csv: buildCSV(headers, body), filename: `Collection Statement ${dateRangeLabel(range.start, range.end)}` };
225	}
226	
227	/* ── 3 · Aged Arrears (overdue invoices, bucketed) ──────────────────── */
228	
229	function AgedArrearsDoc(data: PropertyReportData) {
230	  const now = new Date();
231	  const tmap = byId(data.tenants);
232	  const overdue = data.invoices.filter((i) => !isPaid(i) && !isVoided(i) && daysOverdue(i.dueAt, now) >= 1);
233	  const { buckets, grandTotalCents } = agedBuckets(overdue, (i) => i.dueAt, (i) => i.amountCents ?? 0, now);
234	  const oldest = overdue.reduce((m, i) => Math.max(m, daysOverdue(i.dueAt, now)), 0);
235	
236	  const columns: Column<any>[] = [
237	    { header: "Tenant", flex: 2, render: (i) => tenantOf(i, tmap) },
238	    { header: "Email", flex: 2.6, render: (i) => tmap.get(i.tenantProfileId)?.email ?? "—" },
239	    { header: "Property", flex: 3, render: (i) => addressOf(i, tmap) },
240	    { header: "Amount", flex: 1.5, align: "right", render: (i) => <Money cents={i.amountCents ?? 0} /> },
241	    { header: "Days", flex: 1, align: "right", render: (i) => String(daysOverdue(i.dueAt, now)) },
242	  ];
243	
244	  return (
245	    <Document title="Aged Arrears">
246	      <ReportPage merchant={data.merchant} title="Aged Arrears Report" period={`${scopePrefix(data)}Overdue as at ${fmtDate(now)}`}>
247	        <KpiRow
248	          items={[
249	            { label: "Total Overdue", value: fmtNZD(grandTotalCents), sub: `${overdue.length} invoices` },
250	            { label: "Buckets", value: buckets.filter((b) => b.rows.length > 0).length + " active" },
251	            { label: "Oldest", value: oldest ? `${oldest} days` : "—" },
252	          ]}
253	        />
254	        {buckets
255	          .filter((b) => b.rows.length > 0)
256	          .map((b) => (
257	            <React.Fragment key={b.key}>
258	              <SectionTitle>{`${b.label}  ·  ${fmtNZD(b.totalCents)}  (${b.rows.length})`}</SectionTitle>
259	              <DataTable
260	                columns={columns}
261	                rows={b.rows}
262	                foot={["Subtotal", "", "", fmtNZD(b.totalCents), ""]}
263	              />
264	            </React.Fragment>
265	          ))}
266	        {overdue.length === 0 && <SectionTitle>No overdue invoices — every tenancy is up to date.</SectionTitle>}
267	      </ReportPage>
268	    </Document>
269	  );
270	}
271	
272	/* ── 4 · Annual Income Statement (month-by-month, landscape) ─────────── */
273	
274	interface PropRow {
275	  address: string;
276	  months: number[]; // 12 cents totals
277	  total: number;
278	}
279	
280	function AnnualIncomeDoc(data: PropertyReportData) {
281	  const now = new Date();
282	  const year = now.getFullYear();
283	  const tmap = byId(data.tenants);
284	  const paidThisYear = data.invoices.filter(isPaid).filter((i) => {
285	    const d = i.paidAt ? new Date(i.paidAt) : null;
286	    return d && d.getFullYear() === year;
287	  });
288	
289	  const propMap = new Map<string, number[]>();
290	  for (const i of paidThisYear) {
291	    const addr = addressOf(i, tmap);
292	    const arr = propMap.get(addr) ?? new Array(12).fill(0);
293	    arr[new Date(i.paidAt).getMonth()] += i.amountCents ?? 0;
294	    propMap.set(addr, arr);
295	  }
296	  const rows: PropRow[] = [...propMap.entries()]
297	    .map(([address, months]) => ({ address, months, total: months.reduce((a, b) => a + b, 0) }))
298	    .sort((a, b) => a.address.localeCompare(b.address));
299	
300	  const grandMonths = new Array(12).fill(0);
301	  for (const r of rows) r.months.forEach((v, m) => (grandMonths[m] += v));
302	  const grandTotal = grandMonths.reduce((a, b) => a + b, 0);
303	  const gst = data.merchant.gstRegistered ? calcGST(grandTotal) : null;
304	
305	  const columns: Column<PropRow>[] = [
306	    { header: "Property", flex: 2.6, render: (r) => r.address },
307	    ...MONTHS.map((m, idx) => ({
308	      header: m,
309	      flex: 0.9,
310	      align: "right" as const,
311	      render: (r: PropRow) => money0(r.months[idx]),
312	    })),
313	    { header: "Total", flex: 1.4, align: "right" as const, render: (r: PropRow) => <Money cents={r.total} /> },
314	  ];
315	  const foot = ["Portfolio total", ...grandMonths.map(money0), fmtNZD(grandTotal)];
316	
317	  return (
318	    <Document title={`Annual Income Statement ${year}`}>
319	      <ReportPage merchant={data.merchant} title="Annual Income Statement" period={`${scopePrefix(data)}Calendar year ${year}`} orientation="landscape">
320	        <KpiRow
321	          items={[
322	            { label: "Income Collected", value: fmtNZD(grandTotal), sub: `${year}` },
323	            { label: "Properties", value: String(rows.length) },
324	            { label: "Monthly Average", value: fmtNZD(Math.round(grandTotal / 12)) },
325	          ]}
326	        />
327	        <SectionTitle>Income by property &amp; month</SectionTitle>
328	        <DataTable columns={columns} rows={rows} foot={foot} emptyText={`No rent collected in ${year}.`} />
329	        {gst && (
330	          <>
331	            <SectionTitle>GST Summary (NZ 15%)</SectionTitle>
332	            <KpiRow
333	              items={[
334	                { label: "Income excl. GST", value: fmtNZD(gst.excl) },
335	                { label: "GST", value: fmtNZD(gst.gst) },
336	                { label: "Income incl. GST", value: fmtNZD(gst.incl) },
337	              ]}
338	            />
339	          </>
340	        )}
341	      </ReportPage>
342	    </Document>
343	  );
344	}
345	
346	/* ── Dispatcher (heavy: pulls @react-pdf, so callers import it dynamically) ── */
347	/* The lightweight PROPERTY_REPORT_OPTIONS list lives in ./property-options so a
348	   page can render the modal without loading this module or the PDF engine. */
349	
350	const biz = (data: PropertyReportData) => data.merchant.businessName || "TaptPay";
351	
352	/** Generate and deliver one property report. Throws on an unknown id so the
353	    modal can surface a failure toast. */
354	export async function runPropertyReport(
355	  id: string,
356	  format: ReportFormat,
357	  data: PropertyReportData,
358	  range: DateRange,
359	): Promise<void> {
360	  switch (id) {
361	    case "rent-roll":
362	      await savePdf(RentRollDoc(data), `${biz(data)} Rent Roll`);
363	      return;
364	    case "collection-statement":
365	      if (format === "csv") {
366	        const { csv, filename } = collectionCsv(data, range);
367	        downloadCsv(csv, filename);
368	        return;
369	      }
370	      await savePdf(CollectionStatementDoc(data, range), `${biz(data)} Collection Statement`);
371	      return;
372	    case "aged-arrears":
373	      await savePdf(AgedArrearsDoc(data), `${biz(data)} Aged Arrears`);
374	      return;
375	    case "annual-income":
376	      await savePdf(AnnualIncomeDoc(data), `${biz(data)} Annual Income ${new Date().getFullYear()}`);
377	      return;
378	    default:
379	      throw new Error(`Unknown property report: ${id}`);
380	  }
381	}
382

