1	/* IO edge for report generation: turn a composed @react-pdf <Document> into a
2	   file the merchant actually receives. Everything upstream — report-utils and
3	   the per-vertical report files — is pure and unit-testable; all the
4	   browser-only surface (Blob URLs, anchor downloads) is quarantined here.
5	
6	   Both PDF and CSV are delivered as a direct download — the merchant opens the
7	   saved file and shares it from their own PDF viewer. That's deliberate: the
8	   native Web Share sheet is unreliable inside the app's webview (it can silently
9	   swallow the tap), whereas a download always lands a file they can act on. */
10	import { pdf } from "@react-pdf/renderer";
11	
12	/* The element type `pdf()` accepts (a <Document> at the root). Derived from the
13	   function itself because @react-pdf doesn't export DocumentProps by name. */
14	export type ReportDoc = NonNullable<Parameters<typeof pdf>[0]>;
15	
16	/** Strip anything a filename or Content-Disposition header would choke on and
17	   guarantee the extension. "Rent Roll – June 2026" → "rent-roll-june-2026.pdf". */
18	export function reportFilename(base: string, ext: "pdf" | "csv"): string {
19	  const stem = base
20	    .normalize("NFKD")
21	    .replace(/[^\w\s.-]/g, "") // drop punctuation, em dashes, emoji, macrons decomposed above
22	    .trim()
23	    .replace(/\s+/g, "-")
24	    .replace(/-+/g, "-")
25	    .replace(/^[-.]+|[-.]+$/g, "")
26	    .toLowerCase();
27	  const name = stem || "taptpay-report";
28	  return name.endsWith(`.${ext}`) ? name : `${name}.${ext}`;
29	}
30	
31	/** Render a composed report Document to a PDF Blob. Resolves once @react-pdf
32	   has laid out every page and embedded the fonts. */
33	export function renderPdfBlob(doc: ReportDoc): Promise<Blob> {
34	  return pdf(doc).toBlob();
35	}
36	
37	/** Push any Blob to the user as a download via a short-lived object URL. */
38	function triggerDownload(blob: Blob, filename: string) {
39	  const url = URL.createObjectURL(blob);
40	  const a = document.createElement("a");
41	  a.href = url;
42	  a.download = filename;
43	  a.rel = "noopener";
44	  document.body.appendChild(a);
45	  a.click();
46	  a.remove();
47	  // Revoke on the next tick so the click has committed before the URL dies.
48	  setTimeout(() => URL.revokeObjectURL(url), 0);
49	}
50	
51	/** Render `doc` and download it as a PDF. The merchant opens the saved file and
52	   shares it from their PDF viewer — more reliable inside the webview than the
53	   native share sheet. */
54	export async function savePdf(doc: ReportDoc, filename: string): Promise<void> {
55	  const blob = await renderPdfBlob(doc);
56	  triggerDownload(blob, reportFilename(filename, "pdf"));
57	}
58	
59	/** Download a CSV string (produced by report-utils buildCSV). Prepends a UTF-8
60	   BOM so Excel on Windows reads NZ characters as UTF-8 rather than Latin-1. */
61	export function downloadCsv(csv: string, filename: string) {
62	  const BOM = String.fromCharCode(0xfeff); // UTF-8 BOM for Excel/Windows
63	  const blob = new Blob([BOM + csv], { type: "text/csv;charset=utf-8" });
64	  triggerDownload(blob, reportFilename(filename, "csv"));
