1	/* The four Trades reports (Invoice Summary, Quote Conversion, Aged Receivables,
2	   Client Statement). Builders are plain functions returning a @react-pdf
3	   <Document>. Data is the trades caches: clients (client_profiles), invoices
4	   (job_invoices) and quotes. All money is already integer cents. GST follows the
5	   merchant's trade GST mode (inclusive default) via calcGSTByMode. */
6	import React from "react";
7	import { Document } from "@react-pdf/renderer";
8	
9	import {
10	  ReportPage, SectionTitle, KpiRow, DataTable, DonutStat, Money, StatusText,
11	  type Column, type MerchantHeader,
12	} from "../components";
13	import {
14	  fmtNZD, fmtDate, dateRangeLabel, calcGSTByMode, daysOverdue,
15	  inRange, agedBuckets, sumCents, ratePct, fmtPct, buildCSV,
16	} from "../../report-utils";
17	import { savePdf, downloadCsv } from "../savePdf";
18	import type { ReportFormat, DateRange } from "./types";
19	
20	export interface TradesReportData {
21	  merchant: MerchantHeader;
22	  clients: any[];
23	  invoices: any[];
24	  quotes: any[];
25	  /** Merchant trade GST mode ("inclusive" default). */
26	  gstMode?: string | null;
27	  /** Selected site address when the page is filtered to one site. */
28	  scope?: string;
29	}
30	
31	/* ── Domain helpers ─────────────────────────────────────────────────── */
32	
33	const isPaid = (i: any) => i.status === "paid" || i.status === "paid_external";
34	const isVoided = (i: any) => i.status === "voided";
35	const isOverdue = (i: any, now: Date) =>
36	  !isPaid(i) && !isVoided(i) && i.dueAt != null && new Date(i.dueAt).getTime() < now.getTime();
37	
38	const clientName = (c: any) => [c?.firstName, c?.lastName].filter(Boolean).join(" ").trim() || "—";
39	const byId = (clients: any[]) => new Map<string, any>(clients.map((c) => [c.id, c]));
40	const siteOf = (i: any, cmap: Map<string, any>) => cmap.get(i.clientProfileId)?.siteAddress ?? "—";
41	const nameOf = (i: any, cmap: Map<string, any>) => {
42	  const c = cmap.get(i.clientProfileId);
43	  return c ? clientName(c) : "—";
44	};
45	
46	const KIND_LABEL: Record<string, string> = { deposit: "Deposit", balance: "Balance", full: "Full", recurring: "Recurring" };
47	const kindLabel = (k: string) => KIND_LABEL[k] ?? (k ? k[0].toUpperCase() + k.slice(1) : "—");
48	
49	type StatusKind = "paid" | "overdue" | "sent" | "muted";
50	function invStatus(i: any, now: Date): { kind: StatusKind; label: string } {
51	  if (isPaid(i)) return { kind: "paid", label: "Paid" };
52	  if (isVoided(i)) return { kind: "muted", label: "Voided" };
53	  if (isOverdue(i, now)) return { kind: "overdue", label: "Overdue" };
54	  return { kind: "sent", label: "Sent" };
55	}
56	
57	const scopePrefix = (data: TradesReportData) => (data.scope ? `${data.scope}  ·  ` : "");
58	
59	/* ── 1 · Invoice Summary (period, grouped by kind) ──────────────────── */
60	
61	interface GroupRow {
62	  type: string;
63	  count: number;
64	  invoicedCents: number;
65	  collectedCents: number;
66	  rate: number | null;
67	}
68	
69	function invoiceGroups(data: TradesReportData, range: DateRange): GroupRow[] {
70	  const inPeriod = data.invoices.filter((i) => !isVoided(i) && inRange(i.createdAt, range.start, range.end));
71	  const groups = new Map<string, any[]>();
72	  for (const i of inPeriod) {
73	    const k = i.kind ?? "full";
74	    const arr = groups.get(k) ?? [];
75	    arr.push(i);
76	    groups.set(k, arr);
77	  }
78	  return [...groups.entries()]
79	    .map(([type, invs]) => {
80	      const paid = invs.filter(isPaid);
81	      return {
82	        type: kindLabel(type),
83	        count: invs.length,
84	        invoicedCents: sumCents(invs, (i) => i.amountCents ?? 0),
85	        collectedCents: sumCents(paid, (i) => i.amountCents ?? 0),
86	        rate: ratePct(paid.length, invs.length),
87	      };
88	    })
89	    .sort((a, b) => b.invoicedCents - a.invoicedCents);
90	}
91	
92	function InvoiceSummaryDoc(data: TradesReportData, range: DateRange) {
93	  const rows = invoiceGroups(data, range);
94	  const invoiced = rows.reduce((s, r) => s + r.invoicedCents, 0);
95	  const collected = rows.reduce((s, r) => s + r.collectedCents, 0);
96	  const count = rows.reduce((s, r) => s + r.count, 0);
97	  const gst = calcGSTByMode(invoiced, data.gstMode);
98	
99	  const columns: Column<GroupRow>[] = [
100	    { header: "Type", flex: 2.4, render: (r) => r.type },
101	    { header: "Count", flex: 1.2, align: "right", render: (r) => String(r.count) },
102	    { header: "Invoiced", flex: 2, align: "right", render: (r) => <Money cents={r.invoicedCents} /> },
103	    { header: "Collected", flex: 2, align: "right", render: (r) => <Money cents={r.collectedCents} /> },
104	    { header: "Rate", flex: 1.2, align: "right", render: (r) => fmtPct(r.rate) },
105	  ];
106	
107	  return (
108	    <Document title="Invoice Summary">
109	      <ReportPage merchant={data.merchant} title="Invoice Summary" period={`${scopePrefix(data)}${dateRangeLabel(range.start, range.end)}`}>
110	        <KpiRow
111	          items={[
112	            { label: "Invoiced", value: fmtNZD(invoiced), sub: `${count} invoices` },
113	            { label: "Collected", value: fmtNZD(collected) },
114	            { label: "Collection Rate", value: fmtPct(ratePct(collected, invoiced)) },
115	          ]}
116	        />
117	        <SectionTitle>By invoice type</SectionTitle>
118	        <DataTable
119	          columns={columns}
120	          rows={rows}
121	          foot={["Total", String(count), fmtNZD(invoiced), fmtNZD(collected), ""]}
122	          emptyText="No invoices in this period."
123	        />
124	        <SectionTitle>GST summary ({data.gstMode === "exclusive" ? "exclusive" : "inclusive"}, 15%)</SectionTitle>
125	        <KpiRow
126	          items={[
127	            { label: "Excl. GST", value: fmtNZD(gst.excl) },
128	            { label: "GST", value: fmtNZD(gst.gst) },
129	            { label: "Incl. GST", value: fmtNZD(gst.incl) },
130	          ]}
131	        />
132	      </ReportPage>
133	    </Document>
134	  );
135	}
136	
137	function invoiceSummaryCsv(data: TradesReportData, range: DateRange) {
138	  const rows = invoiceGroups(data, range);
139	  const headers = ["Type", "Count", "Invoiced (NZD)", "Collected (NZD)", "Rate %"];
140	  const body = rows.map((r) => [r.type, r.count, (r.invoicedCents / 100).toFixed(2), (r.collectedCents / 100).toFixed(2), r.rate == null ? "" : String(r.rate)]);
141	  return { csv: buildCSV(headers, body), filename: `Invoice Summary ${dateRangeLabel(range.start, range.end)}` };
142	}
143	
144	/* ── 2 · Quote Conversion (period) ──────────────────────────────────── */
145	
146	const QUOTE_STATUSES = ["draft", "sent", "viewed", "accepted", "declined", "expired"] as const;
147	
148	function QuoteConversionDoc(data: TradesReportData, range: DateRange) {
149	  const quotes = data.quotes.filter((q) => inRange(q.createdAt, range.start, range.end));
150	  const byStatus = QUOTE_STATUSES.map((s) => {
151	    const qs = quotes.filter((q) => q.status === s);
152	    return { status: s, count: qs.length, valueCents: sumCents(qs, (q) => q.totalCents ?? 0) };
153	  });
154	
155	  const sentCount = quotes.filter((q) => q.sentAt || q.status !== "draft").length;
156	  const accepted = quotes.filter((q) => q.status === "accepted");
157	  const conversion = ratePct(accepted.length, sentCount);
158	  const avgValue = quotes.length ? Math.round(sumCents(quotes, (q) => q.totalCents ?? 0) / quotes.length) : 0;
159	
160	  // Average days from sent to accepted, where both timestamps exist.
161	  const spans = accepted
162	    .filter((q) => q.sentAt && q.acceptedAt)
163	    .map((q) => (new Date(q.acceptedAt).getTime() - new Date(q.sentAt).getTime()) / 86_400_000)
164	    .filter((d) => d >= 0);
165	  const avgDays = spans.length ? Math.round((spans.reduce((a, b) => a + b, 0) / spans.length) * 10) / 10 : null;
166	
167	  const columns: Column<{ status: string; count: number; valueCents: number }>[] = [
168	    { header: "Status", flex: 2.4, render: (r) => r.status[0].toUpperCase() + r.status.slice(1) },
169	    { header: "Count", flex: 1.2, align: "right", render: (r) => String(r.count) },
170	    { header: "Value", flex: 2, align: "right", render: (r) => <Money cents={r.valueCents} /> },
171	  ];
172	
173	  return (
174	    <Document title="Quote Conversion">
175	      <ReportPage merchant={data.merchant} title="Quote Conversion" period={`${scopePrefix(data)}${dateRangeLabel(range.start, range.end)}`}>
176	        <KpiRow
177	          items={[
178	            { label: "Quotes", value: String(quotes.length), sub: `${sentCount} sent` },
179	            { label: "Accepted", value: String(accepted.length) },
180	            { label: "Avg Quote", value: fmtNZD(avgValue) },
181	            { label: "Avg Days to Accept", value: avgDays == null ? "—" : String(avgDays) },
182	          ]}
183	        />
184	        <SectionTitle>Conversion</SectionTitle>
185	        <DonutStat pct={conversion ?? 0} centerLabel={fmtPct(conversion)} caption={`${accepted.length} accepted of ${sentCount} sent`} />
186	        <SectionTitle>By status</SectionTitle>
187	        <DataTable
188	          columns={columns}
189	          rows={byStatus}
190	          foot={["Total", String(quotes.length), fmtNZD(sumCents(quotes, (q) => q.totalCents ?? 0))]}
191	          emptyText="No quotes in this period."
192	        />
193	      </ReportPage>
194	    </Document>
195	  );
196	}
197	
198	/* ── 3 · Aged Receivables (bucketed) ────────────────────────────────── */
199	
200	function AgedReceivablesDoc(data: TradesReportData) {
201	  const now = new Date();
202	  const cmap = byId(data.clients);
203	  const overdue = data.invoices.filter((i) => !isPaid(i) && !isVoided(i) && daysOverdue(i.dueAt, now) >= 1);
204	  const { buckets, grandTotalCents } = agedBuckets(overdue, (i) => i.dueAt, (i) => i.amountCents ?? 0, now);
205	  const oldest = overdue.reduce((m, i) => Math.max(m, daysOverdue(i.dueAt, now)), 0);
206	
207	  const columns: Column<any>[] = [
208	    { header: "Client", flex: 2, render: (i) => nameOf(i, cmap) },
209	    { header: "Email", flex: 2.4, render: (i) => cmap.get(i.clientProfileId)?.email ?? "—" },
210	    { header: "Site", flex: 2.6, render: (i) => siteOf(i, cmap) },
211	    { header: "Type", flex: 1.3, render: (i) => kindLabel(i.kind) },
212	    { header: "Amount", flex: 1.5, align: "right", render: (i) => <Money cents={i.amountCents ?? 0} /> },
213	    { header: "Days", flex: 1, align: "right", render: (i) => String(daysOverdue(i.dueAt, now)) },
214	  ];
215	
216	  return (
217	    <Document title="Aged Receivables">
218	      <ReportPage merchant={data.merchant} title="Aged Receivables" period={`${scopePrefix(data)}Overdue as at ${fmtDate(now)}`}>
219	        <KpiRow
220	          items={[
