1	/* Drop-in Export control for the trades vertical. Binds the clients, invoices and
2	   quotes caches (+ merchant GST mode), scopes to the selected site, feeds the
3	   client selector for Client Statement, and dynamically imports the generator. */
4	import { useState } from "react";
5	import { useQuery } from "@tanstack/react-query";
6	
7	import { ReportModal, ExportButton } from "./ReportModal";
8	import { tradesFetch } from "@/lib/trades-api";
9	import { useMerchantProfile } from "@/lib/merchant";
10	import { TRADES_REPORT_OPTIONS } from "@/lib/report-pdf/reports/trades-options";
11	import type { TradesReportData } from "@/lib/report-pdf/reports/trades";
12	
13	const load = (path: string) => () => tradesFetch(path).then((r) => (r.ok ? r.json() : []));
14	
15	/* Job invoices carry no site of their own — resolve it through the client. */
16	function filterBySite(invoices: any[], clients: any[], addr: string | null) {
17	  if (!addr) return { invoices, clients };
18	  const cById = new Map(clients.map((c: any) => [c.id, c]));
19	  return {
20	    invoices: invoices.filter((i: any) => cById.get(i.clientProfileId)?.siteAddress === addr),
21	    clients: clients.filter((c: any) => c.siteAddress === addr),
22	  };
23	}
24	
25	const clientLabel = (c: any) =>
26	  [[c.firstName, c.lastName].filter(Boolean).join(" ").trim(), c.siteAddress].filter(Boolean).join(" · ") || "Client";
27	
28	export function TradesReportsButton({
29	  tone = "onLight",
30	  style,
31	  siteFilter = null,
32	}: {
33	  tone?: "onLight" | "onDark";
34	  style?: React.CSSProperties;
35	  /** Selected site address — reports are scoped to just that site's data. */
36	  siteFilter?: string | null;
37	}) {
38	  const [open, setOpen] = useState(false);
39	  const { data: merchant } = useMerchantProfile();
40	  const { data: clients = [] } = useQuery<any[]>({ queryKey: ["/api/trades/clients"], queryFn: load("/api/trades/clients"), staleTime: 30000 });
41	  const { data: invoices = [] } = useQuery<any[]>({ queryKey: ["/api/trades/invoices"], queryFn: load("/api/trades/invoices"), staleTime: 30000 });
42	  const { data: quotes = [] } = useQuery<any[]>({ queryKey: ["/api/trades/quotes"], queryFn: load("/api/trades/quotes"), staleTime: 30000 });
43	
44	  const { invoices: fInvoices, clients: fClients } = filterBySite(invoices, clients, siteFilter);
45	  const clientIds = new Set(fClients.map((c: any) => c.id));
46	  const fQuotes = siteFilter ? quotes.filter((qq: any) => clientIds.has(qq.clientProfileId)) : quotes;
47	
48	  const data: TradesReportData = {
49	    merchant: merchant ?? {},
50	    clients: fClients,
51	    invoices: fInvoices,
52	    quotes: fQuotes,
53	    gstMode: merchant?.tradeGstMode ?? undefined,
54	    scope: siteFilter ?? undefined,
55	  };
56	
57	  const clientOptions = fClients.filter((c: any) => c.status !== "archived").map((c: any) => ({ id: c.id, label: clientLabel(c) }));
58	
59	  return (
60	    <>
61	      <ExportButton tone={tone} style={style} onClick={() => setOpen(true)} />
62	      {open && (
63	        <ReportModal
64	          title="Trades Reports"
65	          options={TRADES_REPORT_OPTIONS}
66	          clients={clientOptions}
67	          onClose={() => setOpen(false)}
68	          onGenerate={async (id, format, args) => {
69	            const { runTradesReport } = await import("@/lib/report-pdf/reports/trades");
70	            await runTradesReport(id, format, data, args.range, args.clientId);
71	          }}
72	        />
73	      )}
74	    </>
75	  );
76	}
