/* Node stand-in for client/src/lib/report-pdf/savePdf.ts: same exports, but
   writes files to OUT_DIR instead of triggering browser downloads. */
import * as fs from "node:fs";
import * as path from "node:path";
import ReactPDF, { pdf } from "@react-pdf/renderer";

const OUT_DIR = process.env.OUT_DIR || ".";

export type ReportDoc = any;

export function reportFilename(base: string, ext: "pdf" | "csv"): string {
  const stem = base
    .normalize("NFKD")
    .replace(/[^\w\s.-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "")
    .toLowerCase();
  const name = stem || "taptpay-report";
  return name.endsWith(`.${ext}`) ? name : `${name}.${ext}`;
}

export async function renderPdfBlob(doc: ReportDoc): Promise<any> {
  throw new Error("not used in node harness");
}

export async function savePdf(doc: ReportDoc, filename: string): Promise<void> {
  const out = path.join(OUT_DIR, reportFilename(filename, "pdf"));
  const anyPDF: any = ReactPDF as any;
  if (typeof anyPDF.renderToFile === "function") {
    await anyPDF.renderToFile(doc, out);
  } else {
    const buf = await (pdf as any)(doc).toBuffer();
    // toBuffer returns a stream in some builds
    if (buf && typeof buf.pipe === "function") {
      await new Promise((res, rej) => {
        const ws = fs.createWriteStream(out);
        buf.pipe(ws).on("finish", res).on("error", rej);
      });
    } else {
      fs.writeFileSync(out, buf);
    }
  }
  console.log("wrote", out);
}

export function downloadCsv(csv: string, filename: string) {
  const out = path.join(OUT_DIR, reportFilename(filename, "csv"));
  fs.writeFileSync(out, csv, "utf8");
  console.log("wrote", out);
}

