/* Renders all 11 reports with realistic fixture data so the PDFs can be
   eyeballed. Money in cents except retail (decimal strings, as in prod). */
import { runPropertyReport } from "@/lib/report-pdf/reports/property";
import { runRetailReport } from "@/lib/report-pdf/reports/retail";
import { runTradesReport } from "@/lib/report-pdf/reports/trades";

const merchant = {
  businessName: "Harbour City Trades & Property",
  gstNumber: "123-456-789",
  nzbn: "9429041234567",
  gstRegistered: true,
};

const now = new Date();
const daysAgo = (d: number) => new Date(now.getTime() - d * 86_400_000).toISOString();
const range = { start: new Date(now.getTime() - 30 * 86_400_000), end: now };

/* ── Property fixtures ── */
const tenants = [
  { id: "t1", firstName: "Aroha", lastName: "Ngata", email: "aroha@example.co.nz", propertyAddress: "12 Marine Parade, Napier", status: "active" },
  { id: "t2", firstName: "Ben", lastName: "Carter", email: "ben.carter@example.co.nz", propertyAddress: "7B Tinakori Road, Wellington", status: "active" },
  { id: "t3", firstName: "Mei", lastName: "Lin", email: "mei.lin@example.co.nz", propertyAddress: "44 Dominion Road, Auckland", status: "active" },
  { id: "t4", firstName: "Sam", lastName: "O'Leary", email: "sam@example.co.nz", propertyAddress: "3 Papanui Road, Christchurch", status: "archived" },
];
const schedules = [
  { tenantProfileId: "t1", amountCents: 65_000, frequency: "weekly", status: "active" },
  { tenantProfileId: "t2", amountCents: 145_000, frequency: "fortnightly", status: "active" },
  { tenantProfileId: "t3", amountCents: 280_000, frequency: "monthly", status: "active" },
];
let pid = 0;
const pinv = (tenantProfileId: string, amountCents: number, status: string, createdDaysAgo: number, dueDaysAgo: number | null, paidDaysAgo: number | null, kind = "rent") => ({
  id: "pi" + ++pid, tenantProfileId, amountCents, kind, status,
  createdAt: daysAgo(createdDaysAgo),
  dueAt: dueDaysAgo == null ? null : daysAgo(dueDaysAgo),
  paidAt: paidDaysAgo == null ? null : daysAgo(paidDaysAgo),
});
const pInvoices = [
  pinv("t1", 65_000, "paid", 8, 6, 6),
  pinv("t1", 65_000, "paid", 15, 13, 12),
  pinv("t1", 65_000, "pending_dispatch", 1, -6, null),
  pinv("t2", 145_000, "overdue", 20, 12, null),
  pinv("t2", 145_000, "paid", 34, 26, 25),
  pinv("t2", 30_000, "overdue", 75, 65, null, "charge"),
  pinv("t3", 280_000, "paid", 25, 20, 19),
  pinv("t3", 280_000, "dispatched", 4, -3, null),
  pinv("t3", 12_500, "voided", 10, 5, null, "charge"),
  // spread across the year for the annual matrix
  ...[40, 70, 100, 130, 160].map((d) => pinv("t1", 65_000 * 4, "paid", d + 2, d, d)),
  ...[45, 105, 165].map((d) => pinv("t3", 280_000, "paid", d + 2, d, d)),
];
const propertyData = { merchant, tenants, invoices: pInvoices, schedules };

/* ── Retail fixtures (price/totalRefunded are decimal dollar STRINGS) ── */
let rid = 0;
const tx = (price: string, status: string, createdDaysAgo: number, extra: any = {}) => ({
  id: "tx" + ++rid, price, status, createdAt: daysAgo(createdDaysAgo), totalRefunded: "0", ...extra,
});
const transactions = [
  tx("45.00", "completed", 1, { itemName: "Flat white x2 + counter food" }),
  tx("129.99", "completed", 2, { itemName: "Sneakers — Court Classic", isSplit: true }),
  tx("15.50", "completed", 3, { itemName: "Keep cup" }),
  tx("89.00", "refunded", 5, { itemName: "Rain jacket", totalRefunded: "89.00" }),
  tx("240.00", "partially_refunded", 8, { itemName: "Table service — group of 8", totalRefunded: "60.00", splitEnabled: true }),
  tx("32.00", "failed", 9, { itemName: "Gift card" }),
  tx("74.90", "completed", 12, { itemName: "Weekly veg box" }),
  tx("18.00", "processing", 0, { itemName: "Espresso beans 500g" }),
  tx("560.00", "completed", 22, { itemName: "Catering deposit", isSplit: true }),
];
const retailData = { merchant, transactions };

/* ── Trades fixtures ── */
const clients = [
  { id: "c1", firstName: "Rangi", lastName: "Parata", email: "rangi@example.co.nz", siteAddress: "18 Kauri Street, Hamilton", status: "active" },
  { id: "c2", firstName: "Sofia", lastName: "Marsh", email: "sofia@example.co.nz", siteAddress: "2 Beach Road, Mount Maunganui", status: "active" },
  { id: "c3", firstName: "Dev", lastName: "Patel", email: "dev@example.co.nz", siteAddress: "91 Riccarton Road, Christchurch", status: "active" },
];
let tid = 0;
const jinv = (clientProfileId: string, amountCents: number, kind: string, status: string, createdDaysAgo: number, dueDaysAgo: number | null, paidDaysAgo: number | null, jobDetails?: string) => ({
  id: "ji" + ++tid, clientProfileId, amountCents, kind, status, jobDetails,
  createdAt: daysAgo(createdDaysAgo),
  dueAt: dueDaysAgo == null ? null : daysAgo(dueDaysAgo),
  paidAt: paidDaysAgo == null ? null : daysAgo(paidDaysAgo),
});
const jInvoices = [
  jinv("c1", 250_000, "deposit", "paid", 25, 20, 19, "Bathroom reno — deposit"),
  jinv("c1", 480_000, "balance", "overdue", 12, 5, null, "Bathroom reno — balance"),
  jinv("c2", 95_000, "full", "paid", 18, 11, 10, "Hot water cylinder replacement"),
  jinv("c2", 42_000, "full", "dispatched", 3, -4, null, "Annual gas check"),
  jinv("c3", 130_000, "deposit", "overdue", 60, 48, null, "Deck rebuild — deposit"),
  jinv("c3", 15_000, "recurring", "paid", 9, 4, 3, "Gutter clean (quarterly)"),
  jinv("c3", 15_000, "recurring", "voided", 100, 92, null, "Gutter clean (voided)"),
];
const quotes = [
  { id: "q1", clientProfileId: "c1", totalCents: 730_000, status: "accepted", createdAt: daysAgo(28), sentAt: daysAgo(27), acceptedAt: daysAgo(24) },
  { id: "q2", clientProfileId: "c2", totalCents: 95_000, status: "accepted", createdAt: daysAgo(20), sentAt: daysAgo(20), acceptedAt: daysAgo(18) },
  { id: "q3", clientProfileId: "c3", totalCents: 410_000, status: "sent", createdAt: daysAgo(6), sentAt: daysAgo(6) },
  { id: "q4", clientProfileId: "c2", totalCents: 56_000, status: "declined", createdAt: daysAgo(15), sentAt: daysAgo(15) },
  { id: "q5", clientProfileId: "c1", totalCents: 88_000, status: "draft", createdAt: daysAgo(2) },
  { id: "q6", clientProfileId: "c3", totalCents: 120_000, status: "viewed", createdAt: daysAgo(9), sentAt: daysAgo(9) },
];
const tradesData = { merchant, clients, invoices: jInvoices, quotes, gstMode: "inclusive" };

async function main() {
  // property
  await runPropertyReport("rent-roll", "pdf", propertyData as any, range);
  await runPropertyReport("collection-statement", "pdf", propertyData as any, range);
  await runPropertyReport("collection-statement", "csv", propertyData as any, range);
  await runPropertyReport("aged-arrears", "pdf", propertyData as any, range);
  await runPropertyReport("annual-income", "pdf", propertyData as any, range);
  // retail
  await runRetailReport("sales-summary", "pdf", retailData as any, range);
  await runRetailReport("transaction-ledger", "pdf", retailData as any, range);
  await runRetailReport("transaction-ledger", "csv", retailData as any, range);
  await runRetailReport("refunds", "pdf", retailData as any, range);
  // trades
  await runTradesReport("invoice-summary", "pdf", tradesData as any, range);
  await runTradesReport("invoice-summary", "csv", tradesData as any, range);
  await runTradesReport("quote-conversion", "pdf", tradesData as any, range);
  await runTradesReport("aged-receivables", "pdf", tradesData as any, range);
  await runTradesReport("client-statement", "pdf", tradesData as any, range, "c1");
  await runTradesReport("client-statement", "pdf", { ...tradesData, merchant: { ...merchant, businessName: "All Clients Run" } } as any, range, null);
  console.log("ALL REPORTS RENDERED OK");
}

main().catch((e) => { console.error(e); process.exit(1); });

