  await runPropertyReport("collection-statement", "pdf", propertyData as any, range);
  await runPropertyReport("collection-statement", "csv", propertyData as any, range);
  await runPropertyReport("aged-arrears", "pdf", propertyData as any, range);
  await runPropertyReport("annual-income", "pdf", propertyData as any, range);
  // retail
  await runRetailReport("sales-summary", "pdf", retailData as any, range);
  await runRetailReport("transaction-ledger", "pdf", retailData as any, range);
  await runRetailReport("transaction-ledger", "csv", retailData as any, range);
  await runRetailReport("refunds", "pdf", retailData as any, range);
  // trades
  await runTradesReport("invoice-summary", "pdf", tradesData as any, range);
  await runTradesReport("invoice-summary", "csv", tradesData as any, range);
  await runTradesReport("quote-conversion", "pdf", tradesData as any, range);
  await runTradesReport("aged-receivables", "pdf", tradesData as any, range);
  await runTradesReport("client-statement", "pdf", tradesData as any, range, "c1");
  await runTradesReport("client-statement", "pdf", { ...tradesData, merchant: { ...merchant, businessName: "All Clients Run" } } as any, range, null);
  console.log("ALL REPORTS RENDERED OK");
}

main().catch((e) => { console.error(e); process.exit(1); });

