import * as esbuild from "esbuild";
import path from "node:path";

const ROOT = "/home/runner/workspace";
const HERE = path.dirname(new URL(import.meta.url).pathname);
const OUT = path.join(HERE, "out");

await esbuild.build({
  entryPoints: [path.join(HERE, "harness.ts")],
  bundle: true,
  platform: "node",
  format: "cjs",
  target: "node18",
  jsx: "automatic",
  outfile: path.join(OUT, "harness.cjs"),
  loader: { ".ttf": "file" },
  publicPath: OUT, // font imports resolve to absolute fs paths for fontkit
  assetNames: "[name]",
  plugins: [
    {
      name: "alias-and-stub",
      setup(build) {
        build.onResolve({ filter: /^@\// }, (args) => ({
          path: path.join(ROOT, "client/src", args.path.slice(2)) ,
          // let esbuild re-resolve extensions
          namespace: undefined,
          // resolve to actual file
          pluginData: null,
          // use resolveDir trick instead
        }));
        // The savePdf module (browser IO) -> node stub.
        build.onResolve({ filter: /savePdf$/ }, (args) => {
          if (args.importer.includes("report-pdf")) {
            return { path: path.join(HERE, "stub-savePdf.ts") };
          }
        });
      },
    },
  ],
  external: [],
});
console.log("bundled");

